using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FixB5Visuals {
static string R=>Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/B5_Clinical_Tone_20261103"));static string E="Assets/Afrer_Seconds/05.Model/Environment/";const float eps=.0001f;
static string P(Transform t)=>t.parent==null?t.name:P(t.parent)+"/"+t.name;static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
static object CR(Collider c)=>new{path=P(c.transform),type=c.GetType().Name,position=V(c.transform.position),rotation=V(c.transform.eulerAngles),scale=V(c.transform.lossyScale),enabled=c.enabled,trigger=c.isTrigger,boundsCenter=V(c.bounds.center),boundsSize=V(c.bounds.size)};
class Wall{public Transform t;public MeshFilter filter;public MeshRenderer renderer;public Bounds b;public string path;}
class Face{public string path;public int axis,sign;public float plane;public Rect rect;}
static List<Rect> Subtract(Rect a,Rect b){float x0=Mathf.Max(a.xMin,b.xMin),x1=Mathf.Min(a.xMax,b.xMax),y0=Mathf.Max(a.yMin,b.yMin),y1=Mathf.Min(a.yMax,b.yMax);if(x1-x0<=eps||y1-y0<=eps)return new List<Rect>{a};var result=new List<Rect>();Action<float,float,float,float> add=(x,y,w,h)=>{if(w>eps&&h>eps)result.Add(new Rect(x,y,w,h));};add(a.xMin,a.yMin,x0-a.xMin,a.height);add(x1,a.yMin,a.xMax-x1,a.height);add(x0,a.yMin,x1-x0,y0-a.yMin);add(x0,y1,x1-x0,a.yMax-y1);return result;}
static object[] CeilingState(Transform[] ts)=>ts.Where(t=>t.name.Contains("Ceiling")).Select(t=>(object)new{path=P(t),position=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale)}).ToArray();
static Material Change(string name,Color color,bool emission=false){string p=E+"B5/Materials/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(p);if(!mat)throw new Exception("Missing material "+p);string backup=R+"/Backup/"+name+".mat";if(!File.Exists(backup)){File.Copy(p,backup);File.Copy(p+".meta",backup+".meta");}mat.SetColor("_BaseColor",color);if(mat.HasProperty("_Color"))mat.SetColor("_Color",color);if(emission){mat.SetColor("_EmissionColor",new Color(1.48f,1.68f,1.88f));mat.EnableKeyword("_EMISSION");}EditorUtility.SetDirty(mat);return mat;}
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var scene=SceneManager.GetActiveScene();if(!scene.path.EndsWith("Level_B5_Isolation.unity"))throw new Exception("Expected B5");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();Physics.SyncTransforms();var cols=all.SelectMany(t=>t.GetComponents<Collider>()).Select(CR).ToArray();var ceilings=CeilingState(all);File.WriteAllText(R+"/immediate_protection_before.json",JsonConvert.SerializeObject(new{colliders=cols,ceilings},Formatting.Indented));int matBefore=Directory.GetFiles(Application.dataPath,"*.mat",SearchOption.AllDirectories).Length;
var walls=all.Where(t=>P(t).Contains("/Geometry/")&&t.name.Contains("Wall")).Select(t=>new Wall{t=t,filter=t.GetComponent<MeshFilter>(),renderer=t.GetComponent<MeshRenderer>(),path=P(t)}).Where(w=>w.filter&&w.renderer&&w.renderer.enabled&&w.filter.sharedMesh.vertexCount==24).OrderBy(w=>w.path).ToArray();foreach(var w in walls){w.b=w.renderer.bounds;if(Vector3.Distance(w.t.eulerAngles,Vector3.zero)>.01f)throw new Exception("Non-axis-aligned wall "+w.path);}var faces=new List<Face>();var records=new List<object>();var shared=AssetDatabase.LoadAssetAtPath<Material>(E+"Common/Materials/FacilityWall_PaintedConcrete.mat");if(!shared)throw new Exception("Missing shared wall material");
foreach(var w in walls){var verts=new List<Vector3>();var normals=new List<Vector3>();var uvs=new List<Vector2>();var triangles=new List<int>();float removed=0;int cuts=0;for(int axis=0;axis<3;axis++){var axes=Enumerable.Range(0,3).Where(k=>k!=axis).ToArray();int u=axes[0],v=axes[1];foreach(int sign in new[]{-1,1}){float plane=w.b.center[axis]+sign*w.b.extents[axis];var original=new Rect(w.b.min[u],w.b.min[v],w.b.size[u],w.b.size[v]);var remaining=new List<Rect>{original};foreach(var other in walls.Where(o=>o!=w)){float matching=other.b.center[axis]+sign*other.b.extents[axis];bool coplanar=Mathf.Abs(plane-matching)<=eps;float probe=plane+sign*eps*3;bool buried=probe>other.b.min[axis]+eps&&probe<other.b.max[axis]-eps;float otherArea=other.b.size[u]*other.b.size[v];bool otherWins=otherArea>original.width*original.height+eps||(Mathf.Abs(otherArea-original.width*original.height)<=eps&&string.CompareOrdinal(other.path,w.path)<0);if(!buried&&!(coplanar&&otherWins))continue;var cover=new Rect(other.b.min[u],other.b.min[v],other.b.size[u],other.b.size[v]);float oldArea=remaining.Sum(x=>x.width*x.height);remaining=remaining.SelectMany(x=>Subtract(x,cover)).ToList();float loss=oldArea-remaining.Sum(x=>x.width*x.height);if(loss>eps){cuts++;removed+=loss;}}
foreach(var rect in remaining){faces.Add(new Face{path=w.path,axis=axis,sign=sign,plane=plane,rect=rect});var world=new Vector3[4];for(int k=0;k<4;k++){world[k][axis]=plane;world[k][u]=(k==0||k==3)?rect.xMin:rect.xMax;world[k][v]=k<2?rect.yMin:rect.yMax;}var normal=Vector3.zero;normal[axis]=sign;if(Vector3.Dot(Vector3.Cross(world[1]-world[0],world[2]-world[0]),normal)<0)Array.Reverse(world);int start=verts.Count;foreach(var p in world){verts.Add(w.t.InverseTransformPoint(p));normals.Add(w.t.InverseTransformDirection(normal));uvs.Add(new Vector2(axis==0?p.z/2:p.x/2,axis==1?.85f:p.y/4));}triangles.AddRange(new[]{start,start+1,start+2,start,start+2,start+3});}}
}var mesh=new Mesh();mesh.name="B5_"+w.t.parent.parent.name+"_"+w.t.name+"_VisualJunction";mesh.SetVertices(verts);mesh.SetNormals(normals);mesh.SetUVs(0,uvs);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();mesh.RecalculateTangents();string mp=E+"B5/"+mesh.name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(mp);if(!old)AssetDatabase.CreateAsset(mesh,mp);else{EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}w.filter.sharedMesh=mesh;w.renderer.sharedMaterial=shared;EditorUtility.SetDirty(w.filter);EditorUtility.SetDirty(w.renderer);records.Add(new{path=w.path,mesh=mp,cuts,removedDuplicateOrBuriedArea=removed,triangles=triangles.Count/3,colliderUntouched=true});}
var overlaps=new List<object>();for(int i=0;i<faces.Count;i++)for(int j=i+1;j<faces.Count;j++){var a=faces[i];var b=faces[j];if(a.path==b.path||a.axis!=b.axis||a.sign!=b.sign||Mathf.Abs(a.plane-b.plane)>eps)continue;float area=Mathf.Max(0,Mathf.Min(a.rect.xMax,b.rect.xMax)-Mathf.Max(a.rect.xMin,b.rect.xMin))*Mathf.Max(0,Mathf.Min(a.rect.yMax,b.rect.yMax)-Mathf.Max(a.rect.yMin,b.rect.yMin));if(area>.00001f)overlaps.Add(new{a=a.path,b=b.path,axis=a.axis,area});}if(overlaps.Count>0)throw new Exception("Coplanar faces remain "+JsonConvert.SerializeObject(overlaps));
Change("B5_WarmIvory",new Color(.77f,.79f,.82f));Change("B5_SteelGray",new Color(.60f,.63f,.67f));Change("B5_ConcreteFloor",new Color(.31f,.34f,.38f));Change("B5_DarkFrame",new Color(.035f,.043f,.055f));Change("B5_RubberBlack",new Color(.025f,.03f,.035f));Change("B5_Lamp",new Color(.81f,.90f,1),true);Change("Architecture_Rebuilt_AS_PaintedSteel",new Color(.75f,.78f,.81f));Change("Architecture_Rebuilt_AS_Concrete",new Color(.68f,.71f,.74f));Change("Architecture_Rebuilt_AS_Seal",new Color(.035f,.043f,.055f));Change("Architecture_Rebuilt_AS_Fastener",new Color(.29f,.32f,.36f));Change("Architecture_Rebuilt_AS_ObservationLight",new Color(.81f,.90f,1),true);var changedLights=new List<string>();foreach(var light in all.SelectMany(t=>t.GetComponents<Light>()).Where(l=>l.type==LightType.Point&&P(l.transform).EndsWith("/Illumination"))){light.color=new Color(.80f,.89f,1);light.useColorTemperature=false;EditorUtility.SetDirty(light);changedLights.Add(P(light.transform));}
Physics.SyncTransforms();var afterCols=all.SelectMany(t=>t.GetComponents<Collider>()).Select(CR).ToArray();bool physics=JToken.DeepEquals(JToken.Parse(JsonConvert.SerializeObject(cols)),JToken.Parse(JsonConvert.SerializeObject(afterCols)));bool ceiling=JToken.DeepEquals(JToken.Parse(JsonConvert.SerializeObject(ceilings)),JToken.Parse(JsonConvert.SerializeObject(CeilingState(all))));if(!physics||!ceiling)throw new Exception("Protected scene state changed");if(Directory.GetFiles(Application.dataPath,"*.mat",SearchOption.AllDirectories).Length!=matBefore)throw new Exception("Material count changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText(R+"/fix_facts.json",JsonConvert.SerializeObject(new{walls=records,remainingCoplanarOverlaps=overlaps.Count,lights=changedLights,materialCountBefore=matBefore,materialCountAfter=matBefore,newMaterials=0,sharedWallMaterials=1,existingCollidersPreserved=physics,userCeilingTransformsPreserved=ceiling},Formatting.Indented));File.WriteAllText(R+"/faces_after.json",JsonConvert.SerializeObject(faces.Select(f=>new{f.path,f.axis,f.sign,f.plane,xMin=f.rect.xMin,xMax=f.rect.xMax,yMin=f.rect.yMin,yMax=f.rect.yMax}),Formatting.Indented));return "Wall overlap faces removed; white/gray/black palette and pale blue ceiling lights applied; user ceilings and colliders preserved";}}
